const char *ui_text(UiTextId id)
{
    const uint32_t lang = (g_ui.settings.language < UI_LANGUAGE_COUNT) ? g_ui.settings.language : 0U;

    return ((uint32_t)id < (uint32_t)TXT_COUNT) ? k_text[lang][id] : "";
}
